head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.fr_SecuGrpId = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.gDepCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        if (js_market === "1" || js_market === "2") {
            panel_mkt_gubun.hide();
            $c.cm.setColumnProp(grd_List, "TR_MKT_NM", "Show", false);
        } else {
            panel_mkt_gubun.show("");
        }
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);

        // setObjectValue(cmb_DEP_CD, js_dep_cd) ;
        // setObjectValue(cmb_EMP_NO, js_emp_no) ;

        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        fn_GetPar = scwin.getParIsur;
        fn_SetPar = scwin.setParIsur;
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41000.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF41000.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "상장시스템/매매시스템 자료비교목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41000.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41000.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41000.btn_Close_onclick" });
    }
};

