///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const vCmpCd = scwin.getCondition();
    const vCorrCd = rdo_CorrCd.getValue();
    const vEmpNo = cmb_EMP_NO.getValue();
    const vDepCd = cmb_DEP_CD.getValue();
    const vIsurCd = txb_ISUR_CD.getValue();
    let vMarketTpCd = "";
    if (js_market === "1" || js_market === "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = rdo_MARKET_TP_CD.getValue();
    }
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description get Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = txb_COM_NM.getValue();
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};

/**
 * @method
 * @name getCondition
 * @description get Condition 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCondition = function() {
    let vStatCnt = 0;
    let vStatCond = '';
    if (chb_stat_99.checked === true) {
        vStatCond = '';
        vStatCnt++;
    }
    if (chb_stat_01.checked === true) {
        vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '1');
        vStatCnt++;
    }
    if (chb_stat_02.checked === true) {
        vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '2');
        vStatCnt++;
    }
    if (chb_stat_03.checked === true) {
        vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '3');
        vStatCnt++;
    }
    if (chb_stat_04.checked === true) {
        vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '4');
        vStatCnt++;
    }
    if (chb_stat_05.checked === true) {
        vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '5');
        vStatCnt++;
    }
    if (chb_stat_06.checked === true) {
        vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '6');
        vStatCnt++;
    }
    if (chb_stat_07.checked === true) {
        vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '7');
