    }
    return vStatCond;
};

/**
 * @method
 * @name getCondValue
 * @description get Cond Value 처리
 * @param {*} pCnt pCnt
 * @param {*} pVal pVal
 * @param {*} vCode vCode
 * @returns {void}
 * @hidden N
 */
scwin.getCondValue = function(pCnt, pVal, vCode) {
    if (pCnt > 0) {
        pVal += "," + vCode + "";
    } else {
        pVal = vCode;
    }
    return pVal;
};

/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_stat_01, chb_stat_02, chb_stat_03, chb_stat_04, chb_stat_05, chb_stat_06, chb_stat_07, chb_stat_08, chb_stat_09, chb_stat_10];
    if (chb_stat_99.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
